function d(r){return r<=0?{label:"未知",color:"gray",bg:"bg-gray-50 dark:bg-gray-800/50",text:"text-gray-600 dark:text-gray-400",border:"border-gray-200 dark:border-gray-700"}:r<50?{label:"极佳 (Excellent)",color:"emerald",bg:"bg-emerald-50 dark:bg-emerald-950/40",text:"text-emerald-700 dark:text-emerald-400",border:"border-emerald-200 dark:border-emerald-800"}:r<100?{label:"良好 (Good)",color:"blue",bg:"bg-blue-50 dark:bg-blue-950/40",text:"text-blue-700 dark:text-blue-400",border:"border-blue-200 dark:border-blue-800"}:r<200?{label:"一般 (Fair)",color:"amber",bg:"bg-amber-50 dark:bg-amber-950/40",text:"text-amber-700 dark:text-amber-400",border:"border-amber-200 dark:border-amber-800"}:{label:"较慢 (Slow)",color:"rose",bg:"bg-rose-50 dark:bg-rose-950/40",text:"text-rose-700 dark:text-rose-400",border:"border-rose-200 dark:border-rose-800"}}function l(r,e=2){if(r===0)return"0 B";const t=1024,o=e<0?0:e,b=["B","KB","MB","GB","TB"],a=Math.floor(Math.log(r)/Math.log(t));return parseFloat((r/Math.pow(t,a)).toFixed(o))+" "+b[a]}function g(r){if(!r)return"-";try{const e=new Date(r);return isNaN(e.getTime())?r:e.toLocaleString("zh-CN",{year:"numeric",month:"2-digit",day:"2-digit",hour:"2-digit",minute:"2-digit",second:"2-digit",hour12:!1})}catch{return r}}export{l as a,g as f,d as g};
